from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import TaskAttachment, FinancialAuditAttachment

class TaskAttachmentDownloadView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, attachment_id):
        try:
            attachment = TaskAttachment.objects.get(id=attachment_id)
        except TaskAttachment.DoesNotExist:
            return Response({'error': 'Attachment not found'}, status=status.HTTP_404_NOT_FOUND)

        if not attachment.task.project.members.filter(id=request.user.id).exists():
            return Response({'error': 'Not a project member'}, status=status.HTTP_403_FORBIDDEN)

        if isinstance(attachment, FinancialAuditAttachment) and not request.user.is_financial_auditor:
            return Response({'error': 'Financial audit attachments require auditor privilege'}, status=status.HTTP_403_FORBIDDEN)

        return Response({
            'file_name': attachment.file_name,
            'download_url': attachment.file.url,
            'attachment_type': attachment.get_real_instance_class().__name__
        })
